INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q759','nism-5b-z0','A scheme with average net assets of ₹4700 crore incurs total recurring expenses of ₹1.00 crore in a year. Its expense ratio is:','["0.011%","0.032%","0.043%","0.021%"]',3,'TER = 1.00 ÷ 4700 × 100 = 0.021%.',759) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q760','nism-5b-z0','An investor holds 280 units under the IDCW Reinvestment option. IDCW is ₹1 per unit and the ex-IDCW NAV is ₹20. The additional units allotted are:','["13.33","280.00","14.00","28.00"]',2,'Units = (280 × 1) ÷ 20 = 14.00.',760) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q761','nism-5b-z0','An investor redeems 690 units at an NAV of ₹45.90 with an exit load of 1%. The amount received (before tax) is:','["₹31,671.00","₹30,981.00","₹31,987.71","₹31,354.29"]',3,'690 × 45.90 × 0.99.',761) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q762','nism-5b-z0','A distributor has ₹42,00,000 of client AUM in regular plans with a trail rate of 0.5% p.a. The approximate daily trail commission is:','["₹1,726.03","₹57.53","₹690.41","₹1,750.00"]',1,'Daily trail = AUM × rate ÷ 365 = ₹57.53.',762) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q763','nism-5b-z0','An investor sells equity-oriented fund units after 18 months with a long-term capital gain of ₹2,65,000 (no other LTCG in the year). As per the rates in the current workbook, the LTCG tax (ignoring cess) is:','["₹17,500","₹33,125","₹28,000","₹53,000"]',0,'Taxable = 265000 − 1,25,000; tax at 12.5% = ₹17,500.',763) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
