INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q765','nism-5b-z0','A goal costs ₹93,000 today. With inflation of 7% p.a., its cost after 11 years will be approximately:','["₹2,09,454","₹1,95,751","₹1,64,610","₹1,82,945"]',1,'FV = 93000 × (1 + 7%)^11.',765) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
