INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z2-q21','nism-5b-z2','An investor sells equity-oriented fund units after 18 months with a long-term capital gain of ₹4,75,000 (no other LTCG in the year). As per the rates in the current workbook, the LTCG tax (ignoring cess) is:','["₹43,750","₹59,375","₹70,000","₹95,000"]',0,'Taxable = 475000 − 1,25,000; tax at 12.5% = ₹43,750.',21) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
